1	// Package credit 实现本地课程学分与免修的登记、持久化与核对。
2	//
3	// 基本对象：
4	//   - 学生（Student）：以唯一编号登记；
5	//   - 课程（Course）：唯一编号、名称、正整数学分，初始开放，可停开/恢复；
6	//   - 课程要求（Requirement）：属于某名学生，编号在该学生名下唯一，指向一门课程；
7	//   - 修读（Enrollment）：属于某名学生的一项要求，记录学期与编号，结果为
8	//     选课/通过/未通过；
9	//   - 免修（Waiver）：明确指向该学生的一项要求，带编号与非空依据，状态为
10	//     有效/已拒绝/已撤销。
11	//
12	// 所有“重复登记相同内容”的操作都幂等：返回原记录、不新增数据；内容冲突的
13	// 重复请求一律拒绝并保留原记录。
14	package credit
15	
16	import (
17		"errors"
18		"fmt"
19		"strings"
20	)
21	
22	// Result 是修读结果。
23	type Result string
24	
25	const (
26		// Enrolled 已选课、尚未有结果，不计学分。
27		Enrolled Result = "enrolled"
28		// Passed 通过。
29		Passed Result = "passed"
30		// Failed 未通过，不计学分。
31		Failed Result = "failed"
32	)
33	
34	// WaiverStatus 是免修申请的状态。
35	type WaiverStatus string
36	
37	const (
38		// WaiverApproved 有效免修：满足对应要求并获得课程学分。
39		WaiverApproved WaiverStatus = "approved"
40		// WaiverRejected 已拒绝：申请内容与拒绝原因保留在免修历史中。
41		WaiverRejected WaiverStatus = "rejected"
42		// WaiverRevoked 已撤销：原依据保留，要求按修读情况重新判定。
43		WaiverRevoked WaiverStatus = "revoked"
44	)
45	
46	// Course 课程：编号唯一，学分为正整数。
47	type Course struct {
48		ID     string `json:"id"`
49		Name   string `json:"name"`
50		Credit int    `json:"credit"`
51		Open   bool   `json:"open"`
52	}
53	
54	// Student 学生：只有唯一编号。
55	type Student struct {
56		ID string `json:"id"`
57	}
58	
59	// Requirement 课程要求：在所属学生名下编号唯一，指向一门已登记课程。
60	type Requirement struct {
61		ID        string `json:"id"`
62		StudentID string `json:"student"`
63		CourseID  string `json:"course"`
64	}
65	
66	// Enrollment 修读：属于某名学生的一项要求，编号在该学生名下唯一。
67	type Enrollment struct {
68		ID        string `json:"id"`
69		StudentID string `json:"student"`
70		ReqID     string `json:"req"`
71		Term      string `json:"term"`
72		Result    Result `json:"result"`
73		// ResultSeq 是首次提交结果的先后序号，用于确定“最先提交的通过记录”。
74		ResultSeq int `json:"resultSeq,omitempty"`
75	}
76	
77	// Waiver 免修申请。被拒绝或撤销后记录仍保留在免修历史中。
78	type Waiver struct {
79		ID        string       `json:"id"`
80		StudentID string       `json:"student"`
81		ReqID     string       `json:"req"`
82		Basis     string       `json:"basis"`
83		Status    WaiverStatus `json:"status"`
84		// Reason 记录拒绝原因或撤销原因。
85		Reason string `json:"reason,omitempty"`
86	}
87	
88	// Store 是全部记录的内存集合，零值即可用。
89	type Store struct {
90		courses      []*Course
91		students     []*Student
92		requirements []*Requirement
93		enrollments  []*Enrollment
94		waivers      []*Waiver
95	
96		courseByID    map[string]*Course
97		studentByID   map[string]*Student
98		reqByKey      map[ownerKey]*Requirement // (student, reqID)
99		reqByDup      map[ownerKey]string       // (student, course) -> reqID
100		enrByKey      map[ownerKey]*Enrollment  // (student, enrID)
101		waiverByKey   map[ownerKey]*Waiver      // (student, waiverID)
102		nextResultSeq int
103		// dirty 记录自加载以来是否发生过需要落盘的变更（新建被拒绝的免修也算）。
104		dirty bool
105	}
106	
107	// ownerKey 是“所属学生编号 + 该学生名下编号”的复合键。两部分各自按完整
108	// 文字参与比较，因此要求是否存在必须以所属学生和编号都完全一致为准。
109	// 不能用 student + "\x00" + id 之类的字符串拼接：JSON 解码后的编号本身
110	// 允许包含 U+0000 等任意字符，拼接键会把 ("s","x\x00r") 与 ("s\x00x","r")
111	// 两项不同学生的记录混成同一键，导致合法文件被判重复或免修借用他人要求。
112	type ownerKey struct {
113		student string
114		id      string
115	}
116	
117	func reqKey(student, id string) ownerKey { return ownerKey{student, id} }
118	func dupKey(student, course string) ownerKey {
119		return ownerKey{student, course}
120	}
121	
122	func newStore() *Store {
123		s := &Store{}
124		s.resetIndexes()
125		return s
126	}
127	
128	func (s *Store) resetIndexes() {
129		s.courseByID = map[string]*Course{}
130		s.studentByID = map[string]*Student{}
131		s.reqByKey = map[ownerKey]*Requirement{}
132		s.reqByDup = map[ownerKey]string{}
133		s.enrByKey = map[ownerKey]*Enrollment{}
134		s.waiverByKey = map[ownerKey]*Waiver{}
135	}
136	
137	// NewStore 返回空记录集。
138	func NewStore() *Store { return newStore() }
139	
140	// Dirty 报告自加载以来是否发生过需要落盘的变更。
141	// 被拒绝但要保留在免修历史中的申请也计为变更；纯幂等返回与只读核对不计。
142	func (s *Store) Dirty() bool { return s.dirty }
143	
144	// ---------- 查询 ----------
145	
146	// Course 按编号返回课程；不存在返回 nil。
147	func (s *Store) Course(id string) *Course { return s.courseByID[id] }
148	
149	// Courses 按登记顺序返回全部课程。
150	func (s *Store) Courses() []*Course { return append([]*Course(nil), s.courses...) }
151	
152	// Student 按编号返回学生；不存在返回 nil。
153	func (s *Store) Student(id string) *Student { return s.studentByID[id] }
154	
155	// Students 按登记顺序返回全部学生。
156	func (s *Store) Students() []*Student { return append([]*Student(nil), s.students...) }
157	
158	// Requirement 返回某学生名下的要求；不存在（包括要求属于其他学生）返回 nil。
159	func (s *Store) Requirement(student, reqID string) *Requirement {
160		return s.reqByKey[reqKey(student, reqID)]
161	}
162	
163	// Requirements 返回某学生的全部要求（按登记顺序）；学生不存在返回 nil。
164	func (s *Store) Requirements(student string) []*Requirement {
165		if _, ok := s.studentByID[student]; !ok {
166			return nil
167		}
168		var out []*Requirement
169		for _, r := range s.requirements {
170			if r.StudentID == student {
171				out = append(out, r)
172			}
173		}
174		return out
175	}
176	
177	// AllRequirements 按登记顺序返回全部要求。
178	func (s *Store) AllRequirements() []*Requirement {
179		return append([]*Requirement(nil), s.requirements...)
180	}
181	
182	// Enrollment 返回某学生名下的修读；不存在返回 nil。
183	func (s *Store) Enrollment(student, id string) *Enrollment {
184		return s.enrByKey[reqKey(student, id)]
185	}
186	
187	// Enrollments 返回某学生的全部修读（按登记顺序）；学生不存在返回 nil。
188	func (s *Store) Enrollments(student string) []*Enrollment {
189		if _, ok := s.studentByID[student]; !ok {
190			return nil
191		}
192		var out []*Enrollment
193		for _, e := range s.enrollments {
194			if e.StudentID == student {
195				out = append(out, e)
196			}
197		}
198		return out
199	}
200	
201	// Waiver 返回某学生名下的免修申请；不存在返回 nil。
202	func (s *Store) Waiver(student, id string) *Waiver {
203		return s.waiverByKey[reqKey(student, id)]
204	}
205	
206	// Waivers 返回某学生的全部免修历史（按申请顺序）；学生不存在返回 nil。
207	func (s *Store) Waivers(student string) []*Waiver {
208		if _, ok := s.studentByID[student]; !ok {
209			return nil
210		}
211		var out []*Waiver
212		for _, w := range s.waivers {
213			if w.StudentID == student {
214				out = append(out, w)
215			}
216		}
217		return out
218	}
219	
220	// ---------- 学生 ----------
221	
222	// AddStudent 登记学生。编号已存在时原样返回已有学生且 action=existed（幂等）。
223	func (s *Store) AddStudent(id string) (st *Student, action Action, err error) {
224		id = strings.TrimSpace(id)
225		if id == "" {
226			return nil, "", errors.New("学生编号不能为空")
227		}
228		if existing := s.studentByID[id]; existing != nil {
229			return existing, ActionExisted, nil
230		}
231		st = &Student{ID: id}
232		s.students = append(s.students, st)
233		s.studentByID[id] = st
234		s.dirty = true
235		return st, ActionCreated, nil
236	}
237	
238	// ---------- 课程 ----------
239	
240	// Action 描述登记类操作相对已有记录做了什么。
241	type Action string
242	
243	const (
244		// ActionCreated 新建了记录。
245		ActionCreated Action = "created"
246		// ActionExisted 记录已存在且内容一致，原样返回（幂等）。
247		ActionExisted Action = "existed"
248		// ActionUpdated 记录已存在，本次在允许范围内更新了内容。
249		ActionUpdated Action = "updated"
250	)
251	
252	// AddCourse 登记课程，学分为正整数，新课程初始开放。
253	// 编号已存在且名称、学分完全相同时原样返回（幂等），停开/开放状态不变。
254	// 编号相同但学分不同：该课程尚未被任何课程要求引用时允许修改并保持开放
255	// 状态；已经被要求引用的课程不能修改学分，请求被拒绝且课程保持不变。
256	func (s *Store) AddCourse(id, name string, credit int) (c *Course, action Action, err error) {
257		id = strings.TrimSpace(id)
258		name = strings.TrimSpace(name)
259		if id == "" {
260			return nil, "", errors.New("课程编号不能为空")
261		}
262		if name == "" {
263			return nil, "", errors.New("课程名称不能为空")
264		}
265		if credit <= 0 {
266			return nil, "", fmt.Errorf("课程学分必须是正整数，得到 %d", credit)
267		}
268		if existing := s.courseByID[id]; existing != nil {
269			if existing.Name == name && existing.Credit == credit {
270				return existing, ActionExisted, nil
271			}
272			if existing.Credit != credit && s.courseReferenced(id) {
273				return nil, "", fmt.Errorf(
274					"课程 %s 已被课程要求引用，不能修改学分（原学分 %d），原记录保留",
275					id, existing.Credit)
276			}
277			existing.Name = name
278			existing.Credit = credit
279			s.dirty = true
280			return existing, ActionUpdated, nil
281		}
282		c = &Course{ID: id, Name: name, Credit: credit, Open: true}
283		s.courses = append(s.courses, c)
284		s.courseByID[id] = c
285		s.dirty = true
286		return c, ActionCreated, nil
287	}
288	
289	// courseReferenced 报告课程是否被任何学生的课程要求引用。
290	func (s *Store) courseReferenced(id string) bool {
291		for _, r := range s.requirements {
292			if r.CourseID == id {
293				return true
294			}
295		}
296		return false
297	}
298	
299	// SetCourseOpen 设置课程开放状态。课程不存在时报错；状态相同则原样返回。
300	func (s *Store) SetCourseOpen(id string, open bool) (*Course, error) {
301		c := s.courseByID[id]
302		if c == nil {
303			return nil, fmt.Errorf("课程 %s 不存在", id)
304		}
305		if c.Open != open {
306			c.Open = open
307			s.dirty = true
308		}
309		return c, nil
310	}
311	
312	// ---------- 课程要求 ----------
313	
314	// AddRequirement 为学生登记一项指向课程的要求。
315	// 同一要求编号已存在且指向同一课程时返回原要求（幂等）；指向不同课程则拒绝。
316	// 同一学生就同一课程已有要求（即使编号不同）也拒绝。学生或课程不存在时拒绝。
317	func (s *Store) AddRequirement(studentID, reqID, courseID string) (r *Requirement, action Action, err error) {
318		studentID = strings.TrimSpace(studentID)
319		reqID = strings.TrimSpace(reqID)
320		courseID = strings.TrimSpace(courseID)
321		if studentID == "" || reqID == "" {
322			return nil, "", errors.New("学生编号和要求编号不能为空")
323		}
324		if _, ok := s.studentByID[studentID]; !ok {
325			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记课程要求", studentID)
326		}
327		c := s.courseByID[courseID]
328		if c == nil {
329			return nil, "", fmt.Errorf("课程 %s 不存在，不能登记课程要求", courseID)
330		}
331		if existing := s.reqByKey[reqKey(studentID, reqID)]; existing != nil {
332			if existing.CourseID != courseID {
333				return nil, "", fmt.Errorf(
334					"学生 %s 的要求编号 %s 已指向课程 %s，不能改指课程 %s",
335					studentID, reqID, existing.CourseID, courseID)
336			}
337			return existing, ActionExisted, nil
338		}
339		if otherID, ok := s.reqByDup[dupKey(studentID, courseID)]; ok {
340			return nil, "", fmt.Errorf(
341				"学生 %s 已就课程 %s 建立要求 %s，不能重复建立", studentID, courseID, otherID)
342		}
343		r = &Requirement{ID: reqID, StudentID: studentID, CourseID: courseID}
344		s.requirements = append(s.requirements, r)
345		s.reqByKey[reqKey(studentID, reqID)] = r
346		s.reqByDup[dupKey(studentID, courseID)] = reqID
347		s.dirty = true
348		return r, ActionCreated, nil
349	}
350	
351	// ---------- 修读 ----------
352	
353	// AddEnrollment 为学生的一项要求登记某学期的修读，初始状态为“选课”。
354	// 相同（学生、修读编号、要求、学期）的重复登记返回原记录（幂等）；
355	// 相同编号但要求或学期不同则拒绝；课程已停开时不能新增修读
356	// （已登记记录的重复提交仍按幂等返回原记录）。
357	func (s *Store) AddEnrollment(studentID, reqID, term, enrID string) (e *Enrollment, action Action, err error) {
358		studentID = strings.TrimSpace(studentID)
359		reqID = strings.TrimSpace(reqID)
360		term = strings.TrimSpace(term)
361		enrID = strings.TrimSpace(enrID)
362		if studentID == "" || reqID == "" || enrID == "" {
363			return nil, "", errors.New("学生编号、要求编号和修读编号不能为空")
364		}
365		if term == "" {
366			return nil, "", errors.New("学期不能为空")
367		}
368		if _, ok := s.studentByID[studentID]; !ok {
369			return nil, "", fmt.Errorf("学生 %s 不存在，不能登记修读", studentID)
370		}
371		r := s.reqByKey[reqKey(studentID, reqID)]
372		if r == nil {
373			return nil, "", fmt.Errorf("学生 %s 名下不存在要求 %s，不能登记修读", studentID, reqID)
374		}
375		if existing := s.enrByKey[reqKey(studentID, enrID)]; existing != nil {
376			if existing.ReqID != reqID || existing.Term != term {
377				return nil, "", fmt.Errorf(
378					"学生 %s 的修读编号 %s 已用于要求 %s、学期 %s，不能改为要求 %s、学期 %s",
379					studentID, enrID, existing.ReqID, existing.Term, reqID, term)
380			}
381			return existing, ActionExisted, nil
382		}
383		c := s.courseByID[r.CourseID]
384		if c == nil || !c.Open {
385			return nil, "", fmt.Errorf("课程 %s 已停开，不能新增修读", r.CourseID)
386		}
387		e = &Enrollment{
388			ID: enrID, StudentID: studentID, ReqID: reqID, Term: term, Result: Enrolled,
389		}
390		s.enrollments = append(s.enrollments, e)
391		s.enrByKey[reqKey(studentID, enrID)] = e
392		s.dirty = true
393		return e, ActionCreated, nil
394	}
395	
396	// SubmitResult 为修读提交通过/未通过结果。
397	// 重复提交相同结果返回原记录（幂等，不累加学分）；已提交结果后改提另一结果
398	// 一律拒绝并保留原记录。
399	func (s *Store) SubmitResult(studentID, enrID string, result Result) (e *Enrollment, changed bool, err error) {
400		studentID = strings.TrimSpace(studentID)
401		enrID = strings.TrimSpace(enrID)
402		if result != Passed && result != Failed {
403			return nil, false, fmt.Errorf("修读结果只能是 %s 或 %s", Passed, Failed)
404		}
405		if _, ok := s.studentByID[studentID]; !ok {
406			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
407		}
408		e = s.enrByKey[reqKey(studentID, enrID)]
409		if e == nil {
410			return nil, false, fmt.Errorf("学生 %s 名下不存在修读 %s", studentID, enrID)
411		}
412		if e.Result == result {
413			return e, false, nil
414		}
415		if e.Result != Enrolled {
416			return nil, false, fmt.Errorf(
417				"修读 %s 已提交结果“%s”，不能改为“%s”，原结果保留", enrID, zhResult(e.Result), zhResult(result))
418		}
419		s.nextResultSeq++
420		e.Result = result
421		e.ResultSeq = s.nextResultSeq
422		s.dirty = true
423		return e, true, nil
424	}
425	
426	// ---------- 免修 ----------
427	
428	// ApplyWaiver 提交免修申请，依据必须非空。
429	//
430	// 首次提交且内容合法：状态为有效（approved），action=created。
431	// 目标要求不存在（含要求属于其他学生）、依据为空、或该要求已有有效免修：
432	// 申请被拒绝，但申请内容与具体原因保留在该学生的免修历史中，
433	// 返回的申请状态为 rejected（仍属于新建记录，action=created）。
434	// 同一编号已存在：内容（要求、依据）完全相同时返回原申请及其结果
435	// （已拒绝/已撤销的申请不会因重试重新生效）；内容不同则拒绝且不改动原申请。
436	func (s *Store) ApplyWaiver(studentID, reqID, waiverID, basis string) (w *Waiver, action Action, err error) {
437		studentID = strings.TrimSpace(studentID)
438		reqID = strings.TrimSpace(reqID)
439		waiverID = strings.TrimSpace(waiverID)
440		basis = strings.TrimSpace(basis)
441		if studentID == "" || reqID == "" || waiverID == "" {
442			return nil, "", errors.New("学生编号、要求编号和免修编号不能为空")
443		}
444		if _, ok := s.studentByID[studentID]; !ok {
445			return nil, "", fmt.Errorf("学生 %s 不存在，不能申请免修", studentID)
446		}
447		if existing := s.waiverByKey[reqKey(studentID, waiverID)]; existing != nil {
448			if existing.ReqID != reqID || existing.Basis != basis {
449				return nil, "", fmt.Errorf(
450					"学生 %s 的免修编号 %s 已存在（要求 %s、依据 %q），提交内容不同，拒绝修改",
451					studentID, waiverID, existing.ReqID, existing.Basis)
452			}
453			return existing, ActionExisted, nil
454		}
455	
456		w = &Waiver{ID: waiverID, StudentID: studentID, ReqID: reqID, Basis: basis}
457		switch {
458		case s.reqByKey[reqKey(studentID, reqID)] == nil:
459			w.Status = WaiverRejected
460			w.Reason = fmt.Sprintf("目标要求 %s 不存在或不属于该学生", reqID)
461		case basis == "":
462			w.Status = WaiverRejected
463			w.Reason = "免修依据为空"
464		default:
465			if other := s.validWaiver(studentID, reqID); other != nil {
466				w.Status = WaiverRejected
467				w.Reason = fmt.Sprintf("该要求已有有效免修 %s", other.ID)
468				break
469			}
470			w.Status = WaiverApproved
471		}
472		s.waivers = append(s.waivers, w)
473		s.waiverByKey[reqKey(studentID, waiverID)] = w
474		s.dirty = true
475		return w, ActionCreated, nil
476	}
477	
478	// validWaiver 返回某要求当前有效的免修。
479	func (s *Store) validWaiver(studentID, reqID string) *Waiver {
480		for _, w := range s.waivers {
481			if w.StudentID == studentID && w.ReqID == reqID && w.Status == WaiverApproved {
482				return w
483			}
484		}
485		return nil
486	}
487	
488	// RevokeWaiver 撤销有效免修，原依据与撤销状态保留；reason 可填撤销原因。
489	// 重复撤销已撤销的免修：原样返回、changed=false，不改变结果。
490	// 撤销不存在的编号或撤销已被拒绝的申请：明确拒绝。
491	func (s *Store) RevokeWaiver(studentID, waiverID, reason string) (w *Waiver, changed bool, err error) {
492		studentID = strings.TrimSpace(studentID)
493		waiverID = strings.TrimSpace(waiverID)
494		reason = strings.TrimSpace(reason)
495		if _, ok := s.studentByID[studentID]; !ok {
496			return nil, false, fmt.Errorf("学生 %s 不存在", studentID)
497		}
498		w = s.waiverByKey[reqKey(studentID, waiverID)]
499		if w == nil {
500			return nil, false, fmt.Errorf("学生 %s 名下不存在免修 %s，不能撤销", studentID, waiverID)
501		}
502		switch w.Status {
503		case WaiverApproved:
504			w.Status = WaiverRevoked
505			if reason == "" {
506				reason = "手动撤销"
507			}
508			w.Reason = reason
509			s.dirty = true
510			return w, true, nil
511		case WaiverRevoked:
512			return w, false, nil
513		default:
514			return nil, false, fmt.Errorf("免修 %s 已被拒绝，不能撤销（拒绝原因：%s）", waiverID, w.Reason)
515		}
516	}
517

