11	// 本文件为“读取已有记录时，同一学生的同一要求只能有一份有效免修”这项
12	// 业务规则提供回归保障。冲突无法经正常申请流程产生（第二份会在提交时被
13	// 拒绝），因此全部用例直接构造记录文件，聚焦 Load 读取历史这一路径：
14	//   - 文件本身完整、可解析，学生、课程、要求确实存在，两份免修依据非空，
15	//     只要同一学生同一要求下有两份编号不同的 approved 免修就整份拒绝；
16	//   - 一份 approved 与 rejected/revoked 历史共存是合法记录：核对只认那份
17	//     有效免修、学分只计一次，历史与原有原因逐条保留，失效申请不重新生效；
18	//   - 唯一性按“学生 + 要求”界定：不同学生共享要求编号、免修编号互不影响。
19	
20	// writeRecord 将 d 序列化到临时记录文件，返回路径与写入的原始字节，
21	// 供调用方在拒绝读取后逐字节比对。
22	func writeRecord(t *testing.T, d *fileData) (path string, raw []byte) {
23		t.Helper()
24		buf, err := json.MarshalIndent(d, "", "  ")
25		if err != nil {
26			t.Fatalf("序列化测试记录失败：%v", err)
27		}
28		buf = append(buf, '\n')
29		path = filepath.Join(t.TempDir(), "records.json")
30		if err := os.WriteFile(path, buf, 0o600); err != nil {
31			t.Fatalf("写入测试记录失败：%v", err)
32		}
33		return path, buf
34	}
