84	// TestLoadRejectsDuplicateApprovedWaiversInHistory 文件完整可解析、引用齐全、
85	// 两份免修都有非空依据，但同一学生同一要求下有两份编号不同的有效免修：
86	// 无论它们在历史中怎样排列、是否夹杂失效申请、是否另有通过修读、是否还有
87	// 另一名学生的合法同号记录，都必须整份拒绝并保留原文件。
88	func TestLoadRejectsDuplicateApprovedWaiversInHistory(t *testing.T) {
89		approved := func(id, basis string) *Waiver {
90			return &Waiver{ID: id, StudentID: "s1", ReqID: "r1", Basis: basis, Status: WaiverApproved}
91		}
92	
93		t.Run("两份有效免修_先w1后w2", func(t *testing.T) {
94			d := waiverConflictBase(false)
95			d.Waivers = []*Waiver{approved("w1", "学科竞赛获奖"), approved("w2", "外校同层次课程")}
96			path, raw := writeRecord(t, d)
97			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
98			// 先读到的编号应排在冲突说明前面，证明两份都被点名而不是只报后者。
99			if _, _, err := Load(path); err == nil ||
100				!strings.Contains(err.Error(), "有效免修 w1 与 w2") {
101				t.Fatalf("冲突说明应按读取顺序点名 w1 与 w2，得到：%v", err)
102			}
103		})
104	
105		t.Run("两份有效免修_先w2后w1", func(t *testing.T) {
106			d := waiverConflictBase(false)
107			d.Waivers = []*Waiver{approved("w2", "外校同层次课程"), approved("w1", "学科竞赛获奖")}
108			path, raw := writeRecord(t, d)
109			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
110			if _, _, err := Load(path); err == nil ||
111				!strings.Contains(err.Error(), "有效免修 w2 与 w1") {
112				t.Fatalf("交换排列后冲突说明应点名 w2 与 w1，不能只报固定的一份，得到：%v", err)
113			}
114		})
115	
116		t.Run("失效申请夹在中间不改变冲突", func(t *testing.T) {
117			d := waiverConflictBase(false)
118			d.Waivers = []*Waiver{
119				approved("w1", "学科竞赛获奖"),
120				{ID: "wx", StudentID: "s1", ReqID: "r1", Basis: "旧依据",
121					Status: WaiverRejected, Reason: "该要求已有有效免修 w1"},
122				approved("w2", "外校同层次课程"),
123			}
124			path, raw := writeRecord(t, d)
125			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
126		})
127	
128		t.Run("另有通过修读不能掩盖免修冲突", func(t *testing.T) {
129			// 即使该要求已通过修读满足，两份有效免修并存仍然是记录损坏：
130			// 不能拿着通过记录继续核对学分。
131			d := waiverConflictBase(true)
132			d.Waivers = []*Waiver{approved("w1", "学科竞赛获奖"), approved("w2", "外校同层次课程")}
133			path, raw := writeRecord(t, d)
134			assertConflictRejected(t, path, raw, "s1", "r1", "w1", "w2")
135		})
136	
137		t.Run("无关学生的合法同号记录不背锅", func(t *testing.T) {
138			// s2 各自只有一份有效免修，完全合法；s1 名下的冲突仍要整份拒绝，
139			// 且错误应归属 s1，不能误报成 s2 的同一要求被重复取代。
140			d := waiverConflictBase(false)
141			d.Courses = append(d.Courses, &Course{ID: "c2", Name: "线性代数", Credit: 3, Open: true})
142			d.Students = append(d.Students, &Student{ID: "s2"})
143			d.Requirements = append(d.Requirements, &Requirement{ID: "r1", StudentID: "s2", CourseID: "c2"})
144			d.Waivers = []*Waiver{
145				approved("w1", "学科竞赛获奖"),
146				approved("w2", "外校同层次课程"),
147				{ID: "w1", StudentID: "s2", ReqID: "r1", Basis: "s2 的依据", Status: WaiverApproved},
148			}
149			path, raw := writeRecord(t, d)
150			s, existed, err := Load(path)
151			if err == nil {
152				t.Fatalf("s1 名下冲突时必须整份拒绝，不能只加载 s2 的合法部分，得到 store=%v", s)
153			}
154			if !existed {
155				t.Fatalf("冲突记录应标记为已存在，existed=%v", existed)
156			}
157			msg := err.Error()
158			if !strings.Contains(msg, "s1") || !strings.Contains(msg, "w1") || !strings.Contains(msg, "w2") {
159				t.Fatalf("冲突应归属 s1 并点名 w1/w2，得到：%v", err)
160			}
161			if strings.Contains(msg, "学生 s2") {
162				t.Fatalf("s2 只有一份有效免修，不应被点名为冲突方，得到：%v", err)
163			}
164			got, readErr := os.ReadFile(path)
165			if readErr != nil {
166				t.Fatal(readErr)
167			}
168			if string(got) != string(raw) {
169				t.Fatal("拒绝读取不得改写原文件")
170			}
171		})
172	}
