	} else if msg := err.Error(); !strings.Contains(msg, "内容损坏") ||
		!strings.Contains(msg, "s1") || !strings.Contains(msg, "wv") {
		t.Fatalf("错误应点名 s1 的已撤销免修 wv，得到：%v", err)
